def receive(self, amount: int, is_poison: bool = False) -> int:
    if amount < 0:
        raise ValueError("negative damage")
    if not is_poison and self.shield > 0:
        if self.shield >= amount:
            self.shield -= amount
            return amount
        amount -= self.shield
        self.shield = 0
    dealt = min(self.hp, amount)
    self.hp -= dealt
    self.alive = self.hp > 0
    return dealt

